const NOW = 1700000000; // fixed clock — no Date used
const POLICY = { algs: ["RS256"], iss: "https://auth.example.com", aud: "api://orders" };

function validate(t) {
  if (!POLICY.algs.includes(t.header.alg)) return "REJECT alg";
  if (t.payload.iss !== POLICY.iss) return "REJECT iss";
  if (t.payload.aud !== POLICY.aud) return "REJECT aud";
  if (typeof t.payload.exp !== "number" || t.payload.exp <= NOW) return "REJECT exp";
  return "ACCEPT";
}

const tokens = [
  { header: { alg: "none" },  payload: { iss: POLICY.iss, aud: POLICY.aud, exp: NOW + 3600 } },
  { header: { alg: "HS256" }, payload: { iss: POLICY.iss, aud: POLICY.aud, exp: NOW + 3600 } },
  { header: { alg: "RS256" }, payload: { iss: POLICY.iss, aud: POLICY.aud, exp: NOW - 1 } },
  { header: { alg: "RS256" }, payload: { iss: "https://evil.example.com", aud: POLICY.aud, exp: NOW + 3600 } },
  { header: { alg: "RS256" }, payload: { iss: POLICY.iss, aud: "api://reports", exp: NOW + 3600 } },
  { header: { alg: "RS256" }, payload: { iss: POLICY.iss, aud: POLICY.aud, exp: NOW + 3600 } },
];

const out = tokens.map((t, i) => `t${i + 1}: ${validate(t)}`);
console.log(out.join("\n"));

